  1→//! Preflight prompt collection.
  2→
  3→use std::collections::HashMap;
  4→
  5→use crate::error::{BivvyError, Result};
  6→
  7→use super::{Prompt, UserInterface};
  8→
  9→/// Collects all prompts from steps before execution begins.
 10→pub struct PreflightCollector;
 11→
 12→impl PreflightCollector {
 13→    /// Collect all prompts from the given steps interactively.
 14→    ///
 15→    /// Returns a map of prompt key to prompt value.
 16→    pub fn collect(
 17→        prompts: &[Prompt],
 18→        saved_preferences: &HashMap<String, String>,
 19→        ui: &mut dyn UserInterface,
 20→    ) -> Result<HashMap<String, String>> {
 21→        let mut values = HashMap::new();
 22→
 23→        if prompts.is_empty() {
 24→            return Ok(values);
 25→        }
 26→
 27→        ui.show_header("Before we begin, a few questions:");
 28→
 29→        for (idx, prompt) in prompts.iter().enumerate() {
 30→            // Check for saved preference first
 31→            if let Some(saved) = saved_preferences.get(&prompt.key) {
 32→                values.insert(prompt.key.clone(), saved.clone());
 33→                ui.message(&format!(
 34→                    "Using saved preference for '{}': {}",
 35→                    prompt.key, saved
 36→                ));
 37→                continue;
 38→            }
 39→
 40→            ui.show_progress(idx + 1, prompts.len());
 41→            let result = ui.prompt(prompt)?;
 42→            values.insert(prompt.key.clone(), result.as_string());
 43→        }
 44→
 45→        Ok(values)
 46→    }
 47→
 48→    /// Collect prompts in non-interactive mode using defaults.
 49→    pub fn collect_non_interactive(
 50→        prompts: &[Prompt],
 51→        env_overrides: &HashMap<String, String>,
 52→    ) -> Result<HashMap<String, String>> {
 53→        let mut values = HashMap::new();
 54→
 55→        for prompt in prompts {
 56→            // Check environment override first
 57→            let env_key = format!("BIVVY_PROMPT_{}", prompt.key.to_uppercase());
 58→            if let Some(override_value) = env_overrides.get(&env_key) {
 59→                values.insert(prompt.key.clone(), override_value.clone());
 60→                continue;
 61→            }
 62→
 63→            // Use default if available
 64→            if let Some(default) = &prompt.default {
 65→                values.insert(prompt.key.clone(), default.clone());
 66→            } else {
 67→                return Err(BivvyError::ConfigValidationError {
 68→                    message: format!(
 69→                        "Prompt '{}' has no default value and cannot be used in non-interactive mode",
 70→                        prompt.key
 71→                    ),
 72→                });
 73→            }
 74→        }
 75→
 76→        Ok(values)
 77→    }
 78→}
 79→
 80→#[cfg(test)]
 81→mod tests {
 82→    use super::*;
 83→    use crate::ui::PromptType;
 84→
 85→    fn make_prompt(key: &str, default: Option<&str>) -> Prompt {
 86→        Prompt {
 87→            key: key.to_string(),
 88→            question: "Test question?".to_string(),
 89→            prompt_type: PromptType::Input,
 90→            default: default.map(String::from),
 91→        }
 92→    }
