 94→    if let Some(info) = check_for_updates() {
 95→        if info.update_available {
 96→            ui.message(&format!(
 97→                "Update available: {} -> {} (run `bivvy update` to upgrade)",
 98→                info.current, info.latest
 99→            ));
100→        }
